  },
  "bugs": {
    "url": "https://github.com/LucasInstra/opencode-status-popup/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "status",
    "always-on-top",
    "tray",
    "windows"
  ],
